def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        if hp <= 2 or no_water >= 1:
            return min(budget, 40)
        return min(budget, 18)

    total_players = 1 + len(alive)
    expected_winners = max(1, int(supply // WATER_REQ))
    scarcity = total_players - expected_winners

    prev_bids = []
    desperate_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 2 or no_water >= 2:
        base = 63
    elif hp <= 4 or no_water >= 1:
        base = 49
    else:
        if scarcity <= 0:
            base = 16
        elif scarcity == 1:
            base = 28
        elif scarcity == 2:
            base = 38
        else:
            base = 47

    pressure = 0
    if highest_prev >= 60:
        pressure += 6
    elif highest_prev >= 45:
        pressure += 3
    elif highest_prev > 0:
        pressure += 1

    if avg_prev >= 50:
        pressure += 3
    elif avg_prev >= 35:
        pressure += 1

    pressure += min(6, desperate_opp * 2)
    pressure += min(4, rich_opp)

    bid = base + pressure

    if prev_bids and hp > 2 and no_water == 0:
        target = highest_prev + 2
        if scarcity <= 1:
            target = min(target, 40)
        bid = max(bid, target)

    if scarcity <= 0 and hp > 4 and no_water == 0:
        bid = min(bid, 24)

    if budget < 25:
        if hp <= 2 or no_water >= 1:
            bid = budget
        else:
            bid = min(bid, max(0, budget * 0.6))
    elif budget < bid:
        if hp <= 2 or no_water >= 1:
            bid = budget
        else:
            bid = max(0, min(budget, highest_prev + 1 if highest_prev > 0 else budget * 0.5))

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # Default: if no opponents or no useful trace, bid based on our HP.
    if not alive_opps:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.95)
        if hp <= 4:
            return min(budget, DAILY_SALARY * 0.75)
        return min(budget, DAILY_SALARY * 0.55)

    # Extract yesterday bids from immediate previous_trace only.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid'))

    # Estimate how contested it was yesterday.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

        # If they were already willing to pay near our daily salary, match/beat slightly.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp <= 2:
                bid = DAILY_SALARY * 0.95
            elif hp <= 4:
                bid = DAILY_SALARY * 0.85
            else:
                bid = DAILY_SALARY * 0.70
            # Nudge above their second-highest to win without going maximal.
            bid = max(bid, second_prev_bid + 1.0)
            return min(budget, bid)

        # Moderate contention: bid enough to stay competitive.
        if highest_prev_bid >= DAILY_SALARY * 0.60:
            target = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.55)
            if hp <= 3:
                target = max(target, DAILY_SALARY * 0.75)
            return min(budget, target)

    # No/weak trace: use supply to decide aggressiveness.
    # When supply is higher, we can bid less; when lower, we must bid more.
    # supply is float; map to a normalized pressure.
    if supply <= MIN_SUPPLY:
        pressure = 1.0
    elif supply >= MAX_SUPPLY:
        pressure = 0.2
    else:
        pressure = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)

    base = DAILY_SALARY * (0.45 + 0.35 * pressure)

    # If our HP is low, increase bid to avoid further losses.
    if hp <= 2:
        base = DAILY_SALARY * 0.90
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.70)

    # Never exceed budget.
    return min(budget, base)

def get_bid(day_context, my_status, opponents_status):
